def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    lines = []
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            lines.append(("row", r))
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            lines.append(("col", c))
    axis, line = lines[0]
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]
    out = [[bg for _ in range(w)] for _ in range(h)]
    dr = dc = 0
    if axis == "row":
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        if hi < line:
            dr = line - hi - 1
            stripe = lo + dr - 1
        else:
            dr = line - lo + 1
            stripe = hi + dr + 1
        for r, c in pts:
            out[r + dr][c] = grid[r][c]
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        lo, hi = min(c for r, c in pts), max(c for r, c in pts)
        if hi < line:
            dc = line - hi - 1
            stripe = lo + dc - 1
        else:
            dc = line - lo + 1
            stripe = hi + dc + 1
        for r, c in pts:
            out[r][c + dc] = grid[r][c]
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    return out
